#!/usr/bin/env bash
# Sync the CV master outputs (D:/CV, generated by D:/CV/_source/cvmaster.py) into
# the site's public/ folder and into the job-pipeline attachments folder.
# Run from anywhere. Fails loudly if a source file is missing.
set -euo pipefail

SRC="/d/CV"
REPO_ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
DEST="$REPO_ROOT/public"
ATT="$LOCALAPPDATA/hermes/attachments"

FILES=(Alexandre_Roussel_CV_EN.pdf Alexandre_Roussel_CV_FR.pdf)

for f in "${FILES[@]}"; do
  [ -f "$SRC/$f" ] || { echo "MISSING: $SRC/$f"; exit 1; }
done

for f in "${FILES[@]}"; do
  cp "$SRC/$f" "$DEST/$f"
  if [ -d "$ATT" ]; then cp "$SRC/$f" "$ATT/$f"; fi
done

# Verify: served copy must be byte-identical to the master.
for f in "${FILES[@]}"; do
  if cmp -s "$SRC/$f" "$DEST/$f"; then
    echo "ok  $f  ($(stat -c%s "$SRC/$f") bytes)"
  else
    echo "FAIL $f differs after copy"; exit 1
  fi
done

echo
echo "Next: cd '$REPO_ROOT' && pnpm run build && git add -A && git commit -m 'cv: sync master' && git push origin main"
echo "Then wait ~150 s and check prod, e.g.:"
echo "  curl -sL -o /tmp/cv.pdf https://alexandreroussel.com/Alexandre_Roussel_CV_EN.pdf && pdftotext -layout /tmp/cv.pdf - | head -20"
